head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // Global DataList 생성 호출 (dlt_gaugeData 포함)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:400px; height:300px; position:relative;"
    let cStyleParent = scwin.gVar["cStyleParent"];


    let properties = {
        style: cStyle,
    };

    let cList = $c.gcm.createCList(properties);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // fwGaugeChart 은 dlt_gaugeData 바인딩이 필요하므로 parent1 을 부모로 직접 dynamicCreate (cList 의 position:relative 반영)
    strTarget += '<w2:fwGaugeChart ' + strNameSpace + ' ' + cList + ' chartType="angulargauge" ref="data:dlt_gaugeData" valueNode="value"></w2:fwGaugeChart>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "fwGaugeChart",
        strTarget,
        parent1
    );
}
